// Auto-generated specialized encode functions for common configurations.
// The actual implementations are generated by build.rs into OUT_DIR/codegen_encode.rs.

#[cfg(all(
    feature = "simd-avx2",
    target_arch = "x86_64",
    not(target_env = "msvc"),
    not(any(target_os = "android", target_os = "ios"))
))]
include!(concat!(env!("OUT_DIR"), "/codegen_encode.rs"));

#[inline]
#[cfg(all(feature = "std", target_arch = "x86_64", test))]
fn avx2_codegen_available() -> bool {
    FORCED_AVX2_CODEGEN_AVAILABILITY
        .with(|availability| availability.get())
        .unwrap_or_else(|| avx2_codegen_available_for(std::is_x86_feature_detected!("avx2")))
}

#[inline]
#[cfg(all(feature = "std", target_arch = "x86_64", not(test)))]
fn avx2_codegen_available() -> bool {
    avx2_codegen_available_for(std::is_x86_feature_detected!("avx2"))
}

#[inline]
#[cfg(all(feature = "std", not(target_arch = "x86_64")))]
fn avx2_codegen_available() -> bool {
    false
}

#[inline]
#[cfg(not(feature = "std"))]
fn avx2_codegen_available() -> bool {
    avx2_codegen_available_for(cfg!(all(target_arch = "x86_64", target_feature = "avx2")))
}

#[inline]
fn avx2_codegen_available_for(avx2_available: bool) -> bool {
    avx2_available
}

#[cfg(all(test, feature = "std", target_arch = "x86_64"))]
thread_local! {
    static FORCED_AVX2_CODEGEN_AVAILABILITY: std::cell::Cell<Option<bool>> = const { std::cell::Cell::new(None) };
}

#[cfg(all(test, feature = "std", target_arch = "x86_64"))]
pub(crate) fn with_forced_avx2_codegen_availability<T>(
    availability: bool,
    callback: impl FnOnce() -> T,
) -> T {
    struct Restore<'a> {
        slot: &'a std::cell::Cell<Option<bool>>,
        previous: Option<bool>,
    }

    impl Drop for Restore<'_> {
        fn drop(&mut self) {
            self.slot.set(self.previous);
        }
    }

    FORCED_AVX2_CODEGEN_AVAILABILITY.with(|slot| {
        let restore = Restore {
            slot,
            previous: slot.replace(Some(availability)),
        };
        let result = callback();
        drop(restore);
        result
    })
}

#[cfg(all(
    test,
    feature = "simd-avx2",
    target_arch = "x86_64",
    not(target_env = "msvc"),
    not(any(target_os = "android", target_os = "ios"))
))]
mod tests {
    use super::*;

    #[test]
    fn runtime_avx2_codegen_follows_runtime_availability() {
        assert!(avx2_codegen_available_for(true));
        assert!(!avx2_codegen_available_for(false));
    }

    #[cfg(feature = "std")]
    #[test]
    fn generated_avx2_bytes_are_checked_even_when_auto_prefers_gfni() {
        if !std::is_x86_feature_detected!("avx2") {
            return;
        }
        for (data_count, parity_count) in [(4, 2), (6, 3), (8, 3), (8, 4), (10, 4), (12, 4)] {
            let kernel = select_encode_kernel_avx2(data_count, parity_count).unwrap();
            let rows: Vec<Vec<u8>> = (0..parity_count)
                .map(|row| {
                    (0..data_count)
                        .map(|input| match (row + input) % 4 {
                            0 => 0,
                            1 => 1,
                            _ => (row * 17 + input * 11) as u8,
                        })
                        .collect()
                })
                .collect();
            let row_views: Vec<&[u8]> = rows.iter().map(Vec::as_slice).collect();
            for len in [1, 31, 32, 33, 65, 65536] {
                let data: Vec<Vec<u8>> = (0..data_count)
                    .map(|input| (0..len).map(|i| (input * 41 + i * 13) as u8).collect())
                    .collect();
                let data_views: Vec<&[u8]> = data.iter().map(Vec::as_slice).collect();
                let mut parity = vec![vec![0xa5; len]; parity_count];
                let mut views: Vec<&mut [u8]> = parity.iter_mut().map(Vec::as_mut_slice).collect();
                kernel
                    .execute(&row_views, &data_views, &mut views, len)
                    .unwrap();
                for (row, output) in rows.iter().zip(&parity) {
                    for (offset, &actual) in output.iter().enumerate() {
                        let expected = row.iter().zip(&data).fold(0, |sum, (&c, input)| {
                            sum ^ crate::galois_8::mul(c, input[offset])
                        });
                        assert_eq!(
                            actual, expected,
                            "shape {data_count}+{parity_count}, len {len}, offset {offset}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn no_runtime_avx2_cannot_select_a_kernel() {
        let selected = select_encode_kernel_avx2_with_avx2_available(false, 4, 2);
        assert!(selected.is_none());
    }
}
